"""Authoritative definitions: REST, testing, team process and CI/CD."""
from itertools import permutations

from course_builder import C, F, L, M, P, Q, practice, save_group

# GitLab YAML mapping order is immaterial: either job can come first, stages
# may be anywhere at the top level, and stage/script may swap within a job.
# A block must remain together so script never belongs to the wrong job.
PIPELINE_ORDERS = [
    tuple(line for block in blocks for line in block)
    for build in (('b', 'c', 'd'), ('b', 'd', 'c'))
    for test in (('e', 'f', 'g'), ('e', 'g', 'f'))
    for blocks in permutations((('a',), build, test))
    if tuple(line for block in blocks for line in block) != tuple('abcdefg')
]

